// Sammelt die Zeilen und bricht laut ab, wenn nichts kam.
// Eine leere Antwort sieht genauso aus wie ein fehlgeschlagener Abruf - und weiter unten
// wuerde sie das ganze Verzeichnis leeren. Also lieber scheitern als still loeschen.
const zeilen = $input.all().flatMap(i => (Array.isArray(i.json) ? i.json : [i.json]))
  .filter(z => z && z.slug);
if (zeilen.length < 50) {
  throw new Error('Berater-Spiegel: nur ' + zeilen.length + ' Zeilen aus MySQL - Abruf vermutlich fehlgeschlagen (erwartet werden ueber 200)');
}
const gesehen = new Map();
for (const z of zeilen) gesehen.set(String(z.slug), z);
if (gesehen.size !== zeilen.length) {
  throw new Error('Berater-Spiegel: doppelte slugs in der Quelle (' + zeilen.length + ' Zeilen, ' + gesehen.size + ' eindeutige)');
}
return [{ json: { anzahl: gesehen.size, saetze: [...gesehen.values()] } }];

